            return int(circuit)
        elif circuit.startswith('NOT'):
            return 1 - evaluate_circuit(circuit[4:])
        else:
            op, a, b = circuit[1:-1].split()
            a_val = evaluate_circuit(a)
            b_val = evaluate_circuit(b)
            if op == 'AND':
                return a_val and b_val
            elif op == 'OR':
                return a_val or b_val

